function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function metrics(spec: RoleStarterSpec, className = 'metric-grid'): string {
  return `<div class="${className}">${spec.metrics.map(([label, value], index) =>
    `<button type="button" class="metric-card${index === 0 ? ' active' : ''}" data-action data-message="正在查看 ${escapeHtml(label)}"><span>${escapeHtml(label)}</span><b>${escapeHtml(value)}</b><small>${index === 1 ? '需要重点关注' : '较上周期改善'}</small></button>`,
  ).join('')}</div>`;
}

function records(spec: RoleStarterSpec, className = 'record-list'): string {
  return `<div class="${className}">${spec.records.map(([name, value, status], index) =>
    `<button type="button" class="record-row" data-action data-modal="${escapeHtml(name)}"><i>${String(index + 1).padStart(2, '0')}</i><span><b>${escapeHtml(name)}</b><small>${escapeHtml(value)}</small></span><em>${escapeHtml(status)}</em></button>`,
  ).join('')}</div>`;
}

function stages(spec: RoleStarterSpec, className = 'stage-list'): string {
  return `<div class="${className}">${spec.stages.map((stage, index) =>
    `<button type="button" class="stage-card${index === 0 ? ' active' : ''}" data-action data-message="已定位到 ${escapeHtml(stage)}"><i>${String(index + 1).padStart(2, '0')}</i><span><b>${escapeHtml(stage)}</b><small>${index < 2 ? '关键检查已完成' : '点击查看下一步'}</small></span><em>${index < 2 ? '✓' : '→'}</em></button>`,
  ).join('')}</div>`;
}

function titleBlock(spec: RoleStarterSpec, number: string): string {
  return `<div class="title-block"><span>${number} · ${escapeHtml(spec.eyebrow)}</span><h1>${escapeHtml(spec.name)}</h1><p>${escapeHtml(spec.prompt)}。所有关键数据、状态和操作都集中在这个可滚动工作区。</p></div>`;
}

