function roleStarterDocument(spec: RoleStarterSpec): string {
  const layout = LAYOUTS[spec.key];
  if (!layout) throw new Error(`Missing role project layout: ${spec.key}`);
  const content = layout.render(spec);
  return `<!doctype html><html lang="zh-CN" data-role-starter="${spec.role}" data-mode="${escapeHtml(spec.mode)}" data-project-layout="${layout.className}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(spec.name)}</title><style>:root{--accent:${spec.accent};--soft:${spec.soft}}${ROLE_PROJECT_CSS}</style></head><body class="${layout.className}">${content}<div class="project-dialog" id="projectDialog" role="dialog" aria-modal="true" aria-labelledby="projectDialogTitle"><article><small>PROJECT ACTION</small><h2 id="projectDialogTitle">查看详情</h2><p id="projectDialogCopy">此操作会更新当前项目中的可见状态。</p><div class="dialog-actions"><button type="button" id="dialogCancel">取消</button><button type="button" class="confirm" id="dialogConfirm">确认</button></div></article></div><div class="global-status" id="liveStatus" role="status" aria-live="polite">状态已更新</div><script>
(function(){var toast=document.getElementById('liveStatus'),dialog=document.getElementById('projectDialog'),lastFocus=null;function say(text){toast.textContent=text;toast.classList.add('show');clearTimeout(say.t);say.t=setTimeout(function(){toast.classList.remove('show')},1800)}function closeDialog(){dialog.classList.remove('open');if(lastFocus&&lastFocus.focus)lastFocus.focus()}document.querySelectorAll('[data-action]').forEach(function(button){button.addEventListener('click',function(){if(button.disabled)return;if(button.hasAttribute('data-modal')){lastFocus=button;document.getElementById('projectDialogTitle').textContent=button.getAttribute('data-modal')||'查看详情';document.getElementById('projectDialogCopy').textContent='你可以在这里查看详情并确认下一步处理。';dialog.classList.add('open');document.getElementById('dialogCancel').focus();return}var parent=button.parentElement;if(parent){parent.querySelectorAll(':scope > [data-action].active').forEach(function(item){if(item!==button)item.classList.remove('active')})}button.classList.toggle('active');if(button.classList.contains('check-card')||button.classList.contains('decision-row')||button.classList.contains('release-check'))button.classList.toggle('done');if(button.hasAttribute('data-progress'))button.textContent=button.textContent.indexOf('✓')===0?'↻ Re-run':'✓ Completed';say(button.getAttribute('data-message')||'状态已更新：'+button.textContent.trim().slice(0,28))})});document.getElementById('dialogCancel').addEventListener('click',closeDialog);document.getElementById('dialogConfirm').addEventListener('click',function(){closeDialog();say('操作已确认并更新当前状态')});dialog.addEventListener('click',function(event){if(event.target===dialog)closeDialog()});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&dialog.classList.contains('open'))closeDialog()})})();
</script></body></html>`;
}

export const DESIGNBUDDY_ROLE_STARTERS: Readonly<Record<DesignBuddyOperationalRole, readonly DesignBuddyRoleStarterBlueprint[]>> = {
  pm: ROLE_STARTER_SPECS.filter((spec) => spec.role === 'pm').map((spec) => ({ ...spec, html: roleStarterDocument(spec), interactive: true as const })),
  dev: ROLE_STARTER_SPECS.filter((spec) => spec.role === 'dev').map((spec) => ({ ...spec, html: roleStarterDocument(spec), interactive: true as const })),
  admin: ROLE_STARTER_SPECS.filter((spec) => spec.role === 'admin').map((spec) => ({ ...spec, html: roleStarterDocument(spec), interactive: true as const })),
};
